class Array {
public:
    Array(int n) : n_(n), p_(new int[n]()) {}
    ~Array() { delete[] p_; }
    Array(const Array& o) : n_(o.n_), p_(new int[o.n_]) {
        for (int i = 0; i < n_; ++i) p_[i] = o.p_[i];
    }
    Array& operator=(const Array& o) {
        if (this != &o) {
            delete[] p_;
            n_ = o.n_;
            p_ = new int[n_];
            for (int i = 0; i < n_; ++i) p_[i] = o.p_[i];
        }
        return *this;
    }
    int& at(int i) { return p_[i]; }
private:
    int n_;
    int* p_;
};

