void risky() { throw std::runtime_error("失敗"); }

void leaky() {
    int* p = new int(1);
    risky();               // 例外で、下の delete が実行されない
    delete p;
}
void safe() {
    auto p = std::make_unique<int>(1);
    risky();               // 例外でも、自動で解放される
}

