enum class Cmd { Left, Right, Jump, None };

Cmd parse(char c) {
    switch (c) {
        case 'a': return Cmd::Left;
        case 'd': return Cmd::Right;
        case 'j': return Cmd::Jump;
        default:  return Cmd::None;
    }
}

int x = 5, jumps = 0;
for (char c : std::string("aaadj")) {
    switch (parse(c)) {
        case Cmd::Left:  --x; break;
        case Cmd::Right: ++x; break;
        case Cmd::Jump:  ++jumps; break;
        case Cmd::None:  break;
    }
}
std::cout << x << ' ' << jumps << '\n';

enum class State { Idle, Run, Jump };

State next(State s, char in) {
    switch (s) {
        case State::Idle: return in == 'r' ? State::Run : (in == 'j' ? State::Jump : State::Idle);
        case State::Run:  return in == 's' ? State::Idle : (in == 'j' ? State::Jump : State::Run);
        case State::Jump: return State::Idle;
    }
    return s;
}
const char* name(State s) {
    switch (s) {
        case State::Idle: return "Idle";
        case State::Run:  return "Run";
        case State::Jump: return "Jump";
    }
    return "";
}

State s = State::Idle;
for (char in : std::string("rjxs")) {
    s = next(s, in);
    std::cout << name(s) << ' ';
}

