struct Circle { float x, y, r; };

bool hit(const Circle& a, const Circle& b) {
    float dx = a.x - b.x;
    float dy = a.y - b.y;
    float rr = a.r + b.r;
    return dx * dx + dy * dy <= rr * rr;   // sqrt を使わない
}

