class Inventory {
public:
    bool add(const std::string& n, int c) {
        int total = 0;
        for (const auto& kv : items_) total += kv.second;
        if (total + c > cap_) return false;
        items_[n] += c;
        return true;
    }
    bool use(const std::string& n) {
        auto it = items_.find(n);
        if (it == items_.end() || it->second == 0) return false;
        --it->second;
        return true;
    }
    int count(const std::string& n) const {
        auto it = items_.find(n);
        return it == items_.end() ? 0 : it->second;
    }
private:
    std::map<std::string, int> items_;
    int cap_ = 5;
};

