struct Save {
    int version = 1;
    int level = 1;
    int gold = 0;
};

std::string serialize(const Save& s) {
    std::ostringstream os;
    os << s.version << ' ' << s.level << ' ' << s.gold;
    return os.str();
}
bool deserialize(const std::string& text, Save& s) {
    std::istringstream is(text);
    if (!(is >> s.version >> s.level >> s.gold)) return false;
    return s.version == 1;
}

Save a{1, 7, 350};
std::string text = serialize(a);
Save b;
bool ok = deserialize(text, b);
Save c;
bool bad = deserialize("2 1 0", c);
std::cout << text << '\n';
std::cout << ok << ' ' << b.level << ' ' << bad << '\n';

