struct Texture {
    std::string path;
    explicit Texture(const std::string& p) : path(p) {
        std::cout << "load " << path << '\n';
    }
};

class AssetCache {
public:
    std::shared_ptr<Texture> get(const std::string& path) {
        auto it = cache_.find(path);
        if (it != cache_.end()) {
            if (auto sp = it->second.lock()) return sp;
        }
        auto sp = std::make_shared<Texture>(path);
        cache_[path] = sp;
        return sp;
    }
private:
    std::map<std::string, std::weak_ptr<Texture>> cache_;
};

