struct Unit {
    std::string name;
    int hp;
    int atk;
    bool alive() const { return hp > 0; }
};

void attack(const Unit& from, Unit& to) {
    to.hp -= from.atk;
    if (to.hp < 0) to.hp = 0;
    std::cout << from.name << " の攻撃！ " << to.name << " 残りHP " << to.hp << '\n';
}

Unit hero{"Ada", 50, 12};
Unit slime{"Slime", 30, 5};
int turn = 1;
while (hero.alive() && slime.alive()) {
    std::cout << "-- ターン" << turn++ << '\n';
    attack(hero, slime);
    if (slime.alive()) attack(slime, hero);
}
std::cout << (hero.alive() ? "勝利！" : "敗北...") << '\n';
